// Pull the alert list out of whatever the buffer API returned
const alerts = ($input.first().json.alerts || $input.first().json || []);
const list = Array.isArray(alerts) ? alerts : [];

function fingerprint(a) {
  return [
    (a.host || '').toLowerCase(),
    (a.ruleId || '').toLowerCase(),
    (a.severity || '').toLowerCase()
  ].join('|');
}

const FIVE_MIN_MS = 5 * 60 * 1000;
const clustersByKey = {};

for (const a of list) {
  const key = fingerprint(a);
  if (!clustersByKey[key]) clustersByKey[key] = [];
  clustersByKey[key].push(a);
}

const clearClusters = [];
const ambiguousClusters = [];

for (const key of Object.keys(clustersByKey)) {
  const group = clustersByKey[key];
  if (group.length === 1) {
    clearClusters.push({ clusterKey: key, resolution: 'unique', members: group });
    continue;
  }
  // Same fingerprint within a tight time window = clear duplicate, no AI needed
  const times = group.map(g => new Date(g.timestamp).getTime()).sort((x, y) => x - y);
  const tightWindow = (times[times.length - 1] - times[0]) <= FIVE_MIN_MS;

  if (tightWindow) {
    clearClusters.push({ clusterKey: key, resolution: 'duplicate', members: group });
  } else {
    // Same fingerprint but spread out in time - ambiguous, let Claude judge
    ambiguousClusters.push({ clusterKey: key, members: group });
  }
}

return [{
  json: {
    windowTimestamp: new Date().toISOString(),
    clearClusters,
    ambiguousClusters,
    hasAmbiguous: ambiguousClusters.length > 0
  }
}];

