=You are a security operations analyst reducing alert fatigue by deduplicating alerts.

Below are groups of alerts that share the same host, rule, and severity fingerprint but are spread far enough apart in time that we can't be sure they describe the same underlying incident:

{{ JSON.stringify($json.ambiguousClusters, null, 2) }}

For each cluster, decide whether the alerts genuinely describe the same ongoing/related incident (merge them into one case) or are actually separate, unrelated incidents (keep them as separate cases). Base this on the description text, timing pattern, and any escalation you can infer.

Return a JSON object with EXACTLY this shape:
{
  "resolvedClusters": [
    {
      "clusterKey": "string, matching input exactly",
      "resolution": "duplicate" or "separate",
      "reasoning": "one short sentence"
    }
  ]
}

Return ONLY the JSON. No markdown, no explanation.

parameters.jsCode:
const item = $input.item.json;
const upstream = $('Check for Ambiguous Clusters').first().json;

let resolved = [];
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  resolved = parsed.resolvedClusters || [];
} catch (e) {
  // Fallback: if parsing fails, treat every ambiguous cluster as separate (safer than over-merging)
  resolved = (upstream.ambiguousClusters || []).map(c => ({
    clusterKey: c.clusterKey,
    resolution: 'separate',
    reasoning: 'AI clustering unavailable this cycle; kept as separate cases as a safety default.'
  }));
}

const resolutionByKey = {};
for (const r of resolved) resolutionByKey[r.clusterKey] = r;

const finalizedAmbiguous = (upstream.ambiguousClusters || []).map(c => {
  const r = resolutionByKey[c.clusterKey];
  return {
    clusterKey: c.clusterKey,
    resolution: r ? (r.resolution === 'duplicate' ? 'duplicate' : 'unique') : 'unique',
    members: c.members,
    aiReasoning: r ? r.reasoning : ''
  };
});

return { json: { windowTimestamp: upstream.windowTimestamp, clusters: [...upstream.clearClusters, ...finalizedAmbiguous] } };

const severityRank = { critical: 4, high: 3, medium: 2, low: 1 };
const allClusters = [];
for (const item of $input.all()) {
  for (const c of (item.json.clusters || [])) allClusters.push(c);
}

const cases = allClusters.map((c, idx) => {
  const members = c.members || [];
  const rootAlert = members[0] || {};
  const highestSeverity = members.reduce((max, m) => {
    const rank = severityRank[(m.severity || 'low').toLowerCase()] || 1;
    return rank > severityRank[max] ? (m.severity || 'low').toLowerCase() : max;
  }, 'low');

  return {
    caseId: `${(rootAlert.host || 'unknown').replace(/\s+/g, '-')}-${c.clusterKey}-${idx}`,
    title: rootAlert.title || 'Unified security case',
    host: rootAlert.host || '',
    severity: highestSeverity,
    isDuplicateCluster: c.resolution === 'duplicate',
    alertCount: members.length,
    sources: [...new Set(members.map(m => m.source))],
    aiReasoning: c.aiReasoning || '',
    memberExternalIds: members.map(m => m.externalId)
  };
});

return [{ json: { windowTimestamp: new Date().toISOString(), cases } }];
